CREATE SCHEMA "core";

CREATE SCHEMA "projectmanagement";

CREATE SCHEMA "usermanagement";

CREATE TYPE "core"."activity_type" AS ENUM (
  'auto cropper',
  'active measurement'
);

CREATE TYPE "projectmanagement"."model_type" AS ENUM (
  'detection',
  'regression',
  'depth estimation'
);

CREATE TYPE "projectmanagement"."survey_status" AS ENUM (
  'uploaded',
  'preparing',
  'ready for measurement',
  'measuring',
  'finished'
);

CREATE TYPE "usermanagement"."user_status" AS ENUM (
  'active',
  'invited',
  'disabled'
);

CREATE TABLE "core"."images" (
  "image_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "survey_id" integer NOT NULL DEFAULT 0,
  "herd_unit_id" integer NOT NULL DEFAULT 0,
  "name" varchar(75) NOT NULL,
  "img_key" varchar(200) UNIQUE NOT NULL,
  "in_training" boolean DEFAULT false,
  "crops_generated" smallint DEFAULT 0,
  "opened_by_user_id" integer NOT NULL DEFAULT 0,
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "modified" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "image_length_px" integer NOT NULL,
  "image_width_px" integer NOT NULL,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "core"."image_metadata" (
  "metadata_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "image_id" integer NOT NULL DEFAULT 0,
  "captured_at" timestamptz NOT NULL,
  "gps_lon" double precision NOT NULL,
  "gps_lat" double precision NOT NULL,
  "gps_alt_msl_m" double precision NOT NULL,
  "yaw_deg" double precision NOT NULL,
  "pitch_deg" double precision NOT NULL,
  "fov_deg" double precision NOT NULL,
  "terrain_elev_m" double precision NOT NULL,
  "agl_m" double precision NOT NULL,
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "modified" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "core"."image_footprints" (
  "footprint_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "image_id" integer NOT NULL DEFAULT 0,
  "footprint" public.geometry(Polygon, 4326),
  "has_detection" boolean NOT NULL DEFAULT false,
  "footprint_metadata" public.geometry(Polygon, 4326),
  "bbox_wsen" float8[4] NOT NULL,
  "footprint_partial" boolean NOT NULL,
  "area_m2" float8 NOT NULL,
  "area_geodesic_m2" float8 NOT NULL,
  "area_sigma_m2" float8 NOT NULL,
  "area_q05_m2" float8 NOT NULL,
  "area_q95_m2" float8 NOT NULL,
  "dem_name" varchar(36) NOT NULL,
  "georef_status" varchar(12) NOT NULL,
  "n_ties" integer NOT NULL,
  "tie_residual_before_m" float8 NOT NULL,
  "rmse_h_m" float8 NOT NULL,
  "rmse_p50_m" float8 NOT NULL,
  "rmse_p90_m" float8 NOT NULL,
  "n_checkpoints" integer NOT NULL,
  "pose_delta" float8[7] NOT NULL,
  "pose_sigma" float8[7] NOT NULL,
  "pose_free" text[] NOT NULL,
  "pose_cond" float8 NOT NULL,
  "prior_source" varchar(16) NOT NULL,
  "gcps" jsonb NOT NULL,
  "overlay_uri" varchar(200) NOT NULL,
  "georef_modified" timestamptz NOT NULL,
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "modified" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "core"."predictions" (
  "pred_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "image_id" integer NOT NULL DEFAULT 0,
  "model_id" integer NOT NULL DEFAULT 0,
  "reviewed_by_user_id" integer NOT NULL DEFAULT 0,
  "label" integer NOT NULL,
  "score" double precision NOT NULL,
  "box_tx" integer NOT NULL,
  "box_ty" integer NOT NULL,
  "box_bx" integer NOT NULL,
  "box_by" integer NOT NULL,
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "core"."reviewed_area" (
  "reviewed_area_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "image_id" integer NOT NULL,
  "type" core.activity_type NOT NULL DEFAULT 'auto cropper',
  "name" varchar(100) NOT NULL,
  "ra_key" varchar(200) UNIQUE NOT NULL,
  "area_tx" integer NOT NULL,
  "area_ty" integer NOT NULL,
  "area_bx" integer NOT NULL,
  "area_by" integer NOT NULL,
  "reviewed_area_length_px" integer NOT NULL DEFAULT 2100,
  "reviewed_area_width_px" integer NOT NULL DEFAULT 2100,
  "reviewed_by_user_id" integer NOT NULL DEFAULT 0,
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "modified" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "uuid" uuid NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "core"."annotations" (
  "annotation_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "label_id" integer NOT NULL DEFAULT 0,
  "image_id" integer NOT NULL DEFAULT 0,
  "type" core.activity_type NOT NULL DEFAULT 'auto cropper',
  "pred_id" integer NOT NULL,
  "herd_unit_id" integer NOT NULL DEFAULT 0,
  "box_tx" integer NOT NULL,
  "box_ty" integer NOT NULL,
  "box_bx" integer NOT NULL,
  "box_by" integer NOT NULL,
  "created_by_user_id" integer NOT NULL,
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "modified" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "uuid" uuid NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "core"."am_units" (
  "am_unit_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "next_unit_id" integer UNIQUE,
  "previous_unit_id" integer UNIQUE,
  "relative_position" integer,
  "active_measurement_id" integer NOT NULL DEFAULT 0,
  "reviewed_area_id" integer NOT NULL DEFAULT 0,
  "reg_model_id" integer UNIQUE NOT NULL DEFAULT 0,
  "dect_model_id" integer UNIQUE NOT NULL DEFAULT 0,
  "created_by_user_id" integer NOT NULL DEFAULT 0,
  "model_count" double precision,
  "human_count" integer,
  "current_count" double precision,
  "current_ci_lower" double precision,
  "current_ci_upper" double precision,
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "modified" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "uuid" uuid NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "core"."training" (
  "reviewed_area_id" integer,
  "model_id" integer,
  PRIMARY KEY ("reviewed_area_id", "model_id")
);

CREATE TABLE "core"."annotations_reviewed_area" (
  "annotation_id" integer,
  "reviewed_area_id" integer,
  PRIMARY KEY ("annotation_id", "reviewed_area_id")
);

CREATE TABLE "projectmanagement"."projects" (
  "project_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(50) NOT NULL,
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "modified" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "uuid" uuid NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "projectmanagement"."schemas" (
  "schema_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(30) NOT NULL,
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "modified" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "uuid" uuid NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "projectmanagement"."labels" (
  "label_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "schema_id" integer NOT NULL DEFAULT 0,
  "label" smallint NOT NULL,
  "name" varchar(50) NOT NULL,
  "image_link" varchar(1000),
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "modified" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "color" varchar(7) NOT NULL DEFAULT '#FFFFFF',
  "uuid" uuid NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "projectmanagement"."herd_units" (
  "herd_unit_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(30) NOT NULL,
  "habitable_area" double precision,
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "modified" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "uuid" uuid NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "projectmanagement"."models" (
  "model_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "schema_id" integer NOT NULL DEFAULT 0,
  "name" varchar(30) NOT NULL,
  "model_type" projectmanagement.model_type NOT NULL DEFAULT 'detection',
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "modified" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "uuid" uuid NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "projectmanagement"."surveys" (
  "survey_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "survey_date" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "name" varchar(50),
  "status" projectmanagement.survey_status,
  "survey_area" double precision,
  "additional_info" text,
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "modified" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "uuid" uuid NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "projectmanagement"."active_measurements" (
  "active_measurement_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "survey_id" integer NOT NULL DEFAULT 0,
  "label_id" integer NOT NULL DEFAULT 0,
  "random_seed" integer NOT NULL,
  "retraining_cadence" integer NOT NULL DEFAULT 0,
  "target_percentage" double precision,
  "final_count" double precision,
  "final_ci_upper" double precision,
  "final_ci_lower" double precision,
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "modified" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "uuid" uuid NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "projectmanagement"."projects_users" (
  "project_id" integer,
  "user_id" integer,
  "role_id" integer NOT NULL DEFAULT 0,
  PRIMARY KEY ("project_id", "user_id", "role_id")
);

CREATE TABLE "projectmanagement"."projects_schemas" (
  "project_id" integer,
  "schema_id" integer,
  PRIMARY KEY ("project_id", "schema_id")
);

CREATE TABLE "projectmanagement"."projects_herd_units" (
  "project_id" integer,
  "herd_unit_id" integer,
  PRIMARY KEY ("project_id", "herd_unit_id")
);

CREATE TABLE "projectmanagement"."projects_models" (
  "project_id" integer,
  "model_id" integer,
  PRIMARY KEY ("project_id", "model_id")
);

CREATE TABLE "projectmanagement"."surveys_models" (
  "survey_id" integer,
  "model_id" integer,
  PRIMARY KEY ("survey_id", "model_id")
);

CREATE TABLE "projectmanagement"."herd_units_models" (
  "herd_unit_id" integer,
  "model_id" integer,
  PRIMARY KEY ("herd_unit_id", "model_id")
);

CREATE TABLE "projectmanagement"."projects_surveys" (
  "survey_id" integer,
  "project_id" integer,
  PRIMARY KEY ("survey_id", "project_id")
);

CREATE TABLE "projectmanagement"."surveys_herd_units" (
  "survey_id" integer,
  "herd_unit_id" integer,
  PRIMARY KEY ("survey_id", "herd_unit_id")
);

CREATE TABLE "usermanagement"."initialization" (
  "init_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "first_run" boolean NOT NULL DEFAULT true
);

CREATE TABLE "usermanagement"."users" (
  "user_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "default_org_id" integer NOT NULL DEFAULT 0,
  "username" varchar(20) NOT NULL,
  "email" varchar(320) UNIQUE,
  "password_hash" varchar(255),
  "external_auth_id" varchar(255),
  "external_auth_provider" varchar(50),
  "status" usermanagement.user_status,
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "modified" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "last_login" timestamptz,
  "locale" varchar(10),
  "uuid" uuid NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "usermanagement"."roles" (
  "role_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(25) UNIQUE NOT NULL,
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "modified" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "uuid" uuid NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "usermanagement"."organizations" (
  "organization_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(50) UNIQUE NOT NULL,
  "created" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "modified" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "logo_url" varchar(1000),
  "uuid" uuid NOT NULL DEFAULT (gen_random_uuid())
);

CREATE TABLE "usermanagement"."organizations_projects" (
  "project_id" integer,
  "organization_id" integer,
  PRIMARY KEY ("project_id", "organization_id")
);

CREATE TABLE "usermanagement"."organizations_users" (
  "user_id" integer,
  "organization_id" integer,
  "role_id" integer NOT NULL DEFAULT 0,
  PRIMARY KEY ("user_id", "organization_id", "role_id")
);

